{
 "command": "cat scripts/backfill_tax.py && ls scripts",
 "description": "Show backfill script and scripts dir"
}

{
 "command": "cat src/billing/periods.py; echo \"DATABASE_URL=${DATABASE_URL:-<unset>} BACKFILL_BATCH=${BACKFILL_BATCH:-<unset>}\"; git log --oneline -- scripts/backfill_tax.py",
 "description": "Inspect month_window and env vars"
}

{
 "command": "python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"; echo \"TZ=${TZ:-<unset>}\"; date +%Z",
 "description": "Dry-run September backfill with safe batch size"
}

{
 "command": "TZ=UTC python scripts/backfill_tax.py --month 2026-09 --batch-size 500; echo \"exit=$?\"",
 "description": "Rerun dry-run with UTC timezone"
}
